const D = { scale:1, energy:.62, density:.55, speed:1, p:3, q:2, hue:38, x:.5, y:.5, style:'brass', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width,height), cx = width*P.x, cy = height*P.y, t = K.t;
const hsh = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style;
const pp = Math.max(2, Math.round(P.p)), qq = Math.max(1, Math.round(P.q));
const en = P.energy, sc = P.scale;
const R0 = 0.30*u*sc, r0 = (0.10 + 0.03*en)*u*sc;
const N = Math.max(360, Math.min(760, Math.round(360 + P.density*360)));
const flow = t*(0.7 + P.speed*1.6);
const bass = Math.min(0.5, A.bass*0.6);

// grounds
if (sty==='blueprint') background(214, 55, 20);
else if (sty==='engraving') background(38, 12, 58);
else background(224, 40, 8);

// two incommensurate rotations for perpetual, non-repeating tumble
const aX = t*0.13 + 0.4*Math.sin(t*0.061);
const aY = t*0.191 + 0.5*Math.sin(t*0.043+1.1);
const ca=Math.cos(aX), sa=Math.sin(aX), cb=Math.cos(aY), sb=Math.sin(aY);

const pts = [];
for (let i=0;i<=N;i++){
  const th = i/N*Math.PI*2;
  const ta = qq*th, ra = pp*th;
  let X = (R0 + r0*Math.cos(ta))*Math.cos(ra);
  let Y = (R0 + r0*Math.cos(ta))*Math.sin(ra);
  let Z = r0*Math.sin(ta);
  // rot X axis
  let y1 = Y*ca - Z*sa, z1 = Y*sa + Z*ca;
  // rot Y axis
  let x2 = X*cb + z1*sb, z2 = -X*sb + z1*cb;
  pts.push({x:cx+x2, y:cy+y1, z:z2, th});
}
const segs = [];
for (let i=0;i<N;i++){
  const a=pts[i], b=pts[i+1];
  segs.push({a,b, z:(a.z+b.z)*0.5, th:a.th});
}
segs.sort((m,n)=>m.z-n.z);

const zmax = r0+R0*0.02+ r0; // rough extent for normalisation
const ropeW = (0.030 + 0.020*en)*u*sc;
strokeCap(ROUND); strokeJoin(ROUND);
const near = N*0.80; // index threshold in sorted order for shadow

for (let k=0;k<segs.length;k++){
  const s2 = segs[k];
  const dn = (s2.z + R0)/(2*R0); // 0..1 depth, near=1
  const lit = Math.max(0, Math.min(1, dn));
  // flowing highlight band travelling along the cord length
  const band = 0.5 + 0.5*Math.sin(s2.th*qq*1.0 - flow);
  if (sty==='blueprint'){
    stroke(198, 70, 40+45*lit, P.alpha); strokeWeight(ropeW*0.9);
    line(s2.a.x,s2.a.y,s2.b.x,s2.b.y);
    stroke(190, 30, 70+30*lit, P.alpha*0.9); strokeWeight(ropeW*0.28);
    line(s2.a.x,s2.a.y,s2.b.x,s2.b.y);
  } else if (sty==='engraving'){
    stroke(35, 18, 22+18*(1-lit), P.alpha); strokeWeight(ropeW*(0.8+0.5*lit));
    line(s2.a.x,s2.a.y,s2.b.x,s2.b.y);
    if (band>0.62){ stroke(35,10,86,P.alpha*0.5); strokeWeight(ropeW*0.16); line(s2.a.x,s2.a.y,s2.b.x,s2.b.y); }
  } else if (sty==='neon'){
    blendMode(ADD);
    stroke((P.hue+40*band)%360, 85, 26+40*lit, 34*(P.alpha/100)); strokeWeight(ropeW*1.5);
    line(s2.a.x,s2.a.y,s2.b.x,s2.b.y);
    stroke((P.hue+40*band)%360, 45, 88, 80*(P.alpha/100)); strokeWeight(ropeW*0.4);
    line(s2.a.x,s2.a.y,s2.b.x,s2.b.y);
    blendMode(BLEND);
  } else if (sty==='wire'){
    blendMode(ADD);
    stroke((P.hue+30*lit)%360, 55, 30+55*lit, 70*(P.alpha/100)); strokeWeight(1.2+1.4*lit);
    line(s2.a.x,s2.a.y,s2.b.x,s2.b.y);
    blendMode(BLEND);
  } else { // brass metallic
    if (k>near){ drawingContext.shadowBlur = ropeW*0.9; drawingContext.shadowColor='rgba(0,0,0,0.55)'; }
    stroke((P.hue-14)%360, 62, 14+26*lit + 12*bass, P.alpha); strokeWeight(ropeW*(0.9+0.3*lit));
    line(s2.a.x,s2.a.y,s2.b.x,s2.b.y);
    drawingContext.shadowBlur = 0;
    const hb = 40 + 55*lit + 30*band;
    stroke((P.hue+8)%360, 30 - 18*band, Math.min(100,hb+18*bass), P.alpha); strokeWeight(ropeW*0.34);
    line(s2.a.x,s2.a.y,s2.b.x,s2.b.y);
  }
}
drawingContext.shadowBlur = 0;
blendMode(BLEND);
